ROOT = Path(__file__).resolve().parents[2]
SYNC_PATH = "/wecker/sync/iphone"
PROFILE_PATH = SYNC_PATH + "/profile"
ALARM_ACTION = "com.apple.mobiletimer-framework.MobileTimerIntents.MTGetAlarmsIntent"
CAPTURE_FORMAT = "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"
WAKE_FORMAT = "yyyy-MM-dd'T'HH:mm:ssXXX"
RESULT_PATTERN = r"^/wecker/sync/iphone/result\?job=[1-9][0-9]{0,9}&boot=[0-9a-f]{16}$"
OCTET = r"(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])"
BASE_PATTERN = (
    r"^http://(?:10\." + OCTET + r"\." + OCTET + r"\." + OCTET
    + r"|192\.168\." + OCTET + r"\." + OCTET
    + r"|172\.(?:1[6-9]|2[0-9]|3[01])\." + OCTET + r"\." + OCTET + r")$"
)
WEEKDAYS = {
    "mon": r"monday|montag|mon|mo",
    "tue": r"tuesday|dienstag|tues?|di",
    "wed": r"wednesday|mittwoch|wed|mi",
    "thu": r"thursday|donnerstag|thu(?:r|rs)?|do",
    "fri": r"friday|freitag|fri|fr",
    "sat": r"saturday|samstag|sonnabend|sat|sa",
    "sun": r"sunday|sonntag|sun|so",
}
SUMMARY_DAYS = (
    (r"^(?:daily|every day|everyday|täglich|jeden tag)$", "mon tue wed thu fri sat sun"),
    (r"^(?:weekdays|every weekday|wochentags|werktags)$", "mon tue wed thu fri"),
    (r"^(?:weekends|every weekend|wochenende|am wochenende)$", "sat sun"),
    (r"^(?:never|none|nie|keine|no repeat|keine wiederholung)$", ""),
)
REPEAT_RESIDUE = r"\b(?:mon|tue|wed|thu|fri|sat|sun)\b|[\s,;]+"


@dataclass(frozen=True)
class Ref:
    """An action output or named variable, with optional native property access."""

    value: dict

    def property(self, name, coercion=None):
        value = deepcopy(self.value)
        modifiers = value.setdefault("Aggrandizements", [])
        modifiers.append({"Type": "WFPropertyVariableAggrandizement", "PropertyName": name})
        if coercion:
            modifiers.append({"Type": "WFCoercionVariableAggrandizement", "CoercionItemClass": coercion})
        return Ref(value)


def variable(name):
    return Ref({"Type": "Variable", "VariableName": name})


def attachment(value):
    return {"WFSerializationType": "WFTextTokenAttachment", "Value": value.value}


def text(*parts):
    """Encode inline variables with UTF-16 ranges, as required by Shortcuts."""
    string, ranges, position = "", {}, 0
    for part in parts:
        if isinstance(part, Ref):
            ranges["{%d, 1}" % position] = part.value
            part = "\ufffc"
        else:
            part = str(part)
        string += part
        position += len(part.encode("utf-16-le")) // 2
    if not ranges:
        return string
    return {"WFSerializationType": "WFTextTokenString", "Value": {"string": string, "attachmentsByRange": ranges}}


def dictionary_field(values):
    """Encode literal text headers; request bodies are separately serialized JSON."""
    items = []
    for key, value in values.items():
        items.append({
            "WFItemType": 0,
            "WFKey": {"WFSerializationType": "WFTextTokenString", "Value": {"string": key}},
            "WFValue": {"WFSerializationType": "WFTextTokenString", "Value": {"string": value}},
        })
    return {"WFSerializationType": "WFDictionaryFieldValue", "Value": {"WFDictionaryFieldValueItems": items}}


class Shortcut:
    """Small, deterministic builder for the native actions used by this integration."""

    def __init__(self, name):
        self.name = name
        self.actions = []
        self.questions = []

    def identifier(self, purpose):
        return str(uuid.uuid5(uuid.NAMESPACE_URL, "wled:ios-shortcuts:" + self.name + ":" + purpose)).upper()

    def add(self, name, **parameters):
        if not name.startswith("com."):
            name = "is.workflow.actions." + name
        output = self.identifier(str(len(self.actions)))
        parameters["UUID"] = output
        self.actions.append({"WFWorkflowActionIdentifier": name, "WFWorkflowActionParameters": parameters})
        return Ref({"Type": "ActionOutput", "OutputUUID": output, "OutputName": name.rsplit(".", 1)[-1]})

    def comment(self, message):
        self.add("comment", WFCommentActionText=message)

    def set(self, name, value):
        if not isinstance(value, Ref):
            value = self.add("number", WFNumberActionNumber=value) if isinstance(value, (int, float)) else self.add("gettext", WFTextActionText=value)
        self.add("setvariable", WFVariableName=name, WFInput=attachment(value))
        return variable(name)

    def get(self, source, key):
        return self.add("getvalueforkey", WFInput=attachment(source), WFDictionaryKey=key, WFGetDictionaryValueType="Value")

    def matches(self, source, pattern, case_sensitive=False):
        return self.add("text.match", text=attachment(source), WFMatchTextPattern=pattern, WFMatchTextCaseSensitive=case_sensitive)

    def replace(self, source, pattern, replacement):
        return self.add("text.replace", WFInput=attachment(source), WFReplaceTextFind=pattern,
                        WFReplaceTextReplace=replacement, WFReplaceTextRegularExpression=True, WFReplaceTextCaseSensitive=False)

    def format_date(self, source, pattern):
        return self.add("format.date", WFDate=attachment(source), WFDateFormatStyle="Custom", WFDateFormat=pattern, WFTimeFormatStyle="None")

    def adjust_days(self, source, days):
        magnitude = attachment(days) if isinstance(days, Ref) else days
        return self.add("adjustdate", WFDate=attachment(source), WFAdjustOperation="Add",
                        WFDuration={"WFSerializationType": "WFQuantityFieldValue", "Value": {"Magnitude": magnitude, "Unit": "days"}})

    @contextmanager
    def condition(self, source, operator, value=None, value_type="text"):
        group = self.identifier("if:" + str(len(self.actions)))
        parameters = {"GroupingIdentifier": group, "WFControlFlowMode": 0, "WFCondition": operator,
                      "WFInput": {"Type": "Variable", "Variable": attachment(source)}}
        if value is not None:
            key = {"number": "WFNumberValue", "date": "WFDate", "text": "WFConditionalActionString"}[value_type]
            parameters[key] = attachment(value) if isinstance(value, Ref) else value
        self.add("conditional", **parameters)

        def otherwise():
            self.add("conditional", GroupingIdentifier=group, WFControlFlowMode=1)

        yield otherwise
        self.add("conditional", GroupingIdentifier=group, WFControlFlowMode=2)

    @contextmanager
    def repeat(self, count=None, items=None):
        group = self.identifier("repeat:" + str(len(self.actions)))
        action = "repeat.each" if items is not None else "repeat.count"
        parameters = {"GroupingIdentifier": group, "WFControlFlowMode": 0}
        parameters["WFInput" if items is not None else "WFRepeatCount"] = attachment(items) if items is not None else count
        self.add(action, **parameters)
        yield variable("Repeat Item" if items is not None else "Repeat Index")
        self.add(action, GroupingIdentifier=group, WFControlFlowMode=2)

    def notify(self, *message):
        self.add("notification", WFNotificationActionTitle="WLED", WFNotificationActionBody=text(*message), WFNotificationActionSound=False)

    def fail(self, *message):
        self.notify(*message)
        self.add("exit")

    def require(self, source, *message):
        with self.condition(source, 101):
            self.fail(*message)

    def require_equal(self, source, value, *message, value_type="number"):
        with self.condition(source, 5, value, value_type):
            self.fail(*message)

    def check_error(self, source):
        keys = self.add("getvalueforkey", WFInput=attachment(source), WFGetDictionaryValueType="All Keys")
        with self.condition(keys, 99, "error"):
            error = self.get(source, "error")
            with self.condition(error, 100):
                self.fail("WLED rejected the request: ", error, ". Previous confirmed data was not replaced by this error.")

    def request(self, url, body=None):
        parameters = {"WFURL": url, "WFHTTPMethod": "GET" if body is None else "POST"}
        if body is not None:
            parameters.update(WFHTTPBodyType="File", WFRequestVariable=attachment(body),
                              WFHTTPHeaders=dictionary_field({"Content-Type": "application/json"}))
        response = self.add("downloadurl", **parameters)
        document = self.add("detect.dictionary", WFInput=attachment(response))
        self.check_error(document)
        return document

    def base_url(self):
        index = len(self.actions)
        source = self.add("gettext", WFTextActionText="http://WLED-IP")
        self.questions.append({"Category": "Parameter", "ActionIndex": index, "ParameterKey": "WFTextActionText",
                               "Text": "Enter WLED's fixed home-network IPv4 URL, e.g. http://192.168.178.32 (no trailing path).",
                               "DefaultValue": "http://WLED-IP"})
        source = self.add("text.trimwhitespace", WFInput=attachment(source))
        source = self.replace(source, r"/$", "")
        self.require(self.matches(source, BASE_PATTERN), "Set a direct http:// IPv4 address in your trusted home network; no proxy, hostname or public URL.")
        return source

    def capture(self):
        now = self.add("date", WFDateActionMode="Current Date")
        return now, self.format_date(now, CAPTURE_FORMAT)

    def normalized_days(self, source, summary=False):
        result = self.add("text.trimwhitespace", WFInput=attachment(source))
        if summary:
            for pattern, replacement in SUMMARY_DAYS:
                result = self.replace(result, pattern, replacement)
        for day, alternatives in WEEKDAYS.items():
            result = self.replace(result, r"\b(?:" + alternatives + r")\b\.?", day)
        return result

    def select_wake(self, now):
        """Read-only scan: exact WLED substring, explicit enabled state and weekday-aware dates."""
        self.comment("AI: below section was generated by an AI\nOnly normal Clock alarms with case-sensitive WLED in Label qualify. Clock fields must be checked on the actual iPhone. Unsupported/malformed readings abort, never clear the slot.\nAI: end")
        best = self.set("WLED next date", self.adjust_days(now, 8))
        found = self.set("WLED found", 0)
        label = self.set("WLED next label", "")
        alarms = self.add(ALARM_ACTION, WFContentItemLimitEnabled=False)
        with self.repeat(items=alarms) as item:
            alarm = self.set("WLED current alarm", item)
            alarm_label = self.add("detect.text", WFInput=attachment(alarm.property("Label")))
            with self.condition(self.matches(alarm_label, "WLED", True), 100):
                enabled = self.add("detect.text", WFInput=attachment(alarm.property("Is Enabled")))
                self.require(self.matches(enabled, r"^(?:true|false|yes|no|ja|nein|1|0)$"),
                             "Clock did not expose a usable Is Enabled value for ", alarm_label, ". No sync was sent.")
                with self.condition(self.matches(enabled, r"^(?:true|yes|ja|1)$"), 100):
                    self.require(alarm.property("Time"), "Clock did not expose Time. No sync was sent.")
                    alarm_time = self.format_date(alarm.property("Time"), "HH:mm")
                    self.require(self.matches(alarm_time, r"^(?:[01][0-9]|2[0-3]):[0-5][0-9]$"), "Invalid Clock time. No sync was sent.")
                    repeat_text = self.add("text.combine", text=attachment(alarm.property("Repeat")), WFTextSeparator="New Lines")
                    days = self.normalized_days(repeat_text, summary=True)
                    unknown = self.replace(days, REPEAT_RESIDUE, "")
                    with self.condition(unknown, 100):
                        self.fail("Unsupported Clock repeat value: ", repeat_text, ". No sync was sent.")
                    with self.repeat(count=8) as index:
                        offset = self.add("calculateexpression", WFExpression=text(index, " - 1"))
                        day = self.adjust_days(now, offset)
                        date_text = self.format_date(day, "yyyy-MM-dd")
                        weekday = self.normalized_days(self.format_date(day, "EEEE"))
                        self.require(self.matches(weekday, r"^(?:mon|tue|wed|thu|fri|sat|sun)$"), "Use an English/German Gregorian calendar on the iPhone. No sync was sent.")
                        allowed = self.set("WLED day allowed", 1)
                        with self.condition(days, 100):
                            self.set("WLED day allowed", 0)
                            with self.condition(self.matches(days, text(r"\b", weekday, r"\b")), 100):
                                self.set("WLED day allowed", 1)
                        with self.condition(allowed, 4, 1, "number"):
                            candidate = self.add("date", WFDateActionMode="Specified Date", WFDateActionDate=text(date_text, "T", alarm_time, ":00"))
                            with self.condition(candidate, 2, now, "date"):
                                # Do not silently reinterpret a nonexistent spring-forward time.
                                round_trip = self.format_date(candidate, "yyyy-MM-dd'T'HH:mm")
                                expected = self.add("gettext", WFTextActionText=text(date_text, "T", alarm_time))
                                self.require_equal(round_trip, expected, "Clock time falls in an unsupported calendar/DST gap. No sync was sent.", value_type="text")
                                with self.condition(candidate, 0, best, "date"):
                                    self.set("WLED next date", candidate)
                                    self.set("WLED found", 1)
                                    self.set("WLED next label", alarm_label)
        return found, best, label

    def send_confirmed(self, base, path, body, message):
        """Follow only the server's bounded same-origin job URL; never confuse 202 with success."""
        receipt = self.request(text(base, path), body)
        result_path = self.get(receipt, "resultUrl")
        self.require(self.matches(result_path, RESULT_PATTERN, True), "Missing/invalid job receipt. Save is unconfirmed; check WLED Alarm Status.")
        job = self.get(receipt, "job")
        with self.repeat(count=12):
            self.add("delay", WFDelayTime=1)
            result = self.request(text(base, result_path))
            confirmed = self.get(result, "confirmed")
            with self.condition(confirmed, 4, 1, "number"):
                self.require_equal(self.get(result, "version"), 2, "Unexpected sync API version; save is unconfirmed.")
                self.require_equal(self.get(result, "job"), job, "Job mismatch; save is unconfirmed.")
                self.notify(message, "\nDurably saved. Light runner enabled: ", self.get(result, "enabled"))
                self.add("output", WFOutput=text(message), WFNoOutputSurfaceBehavior="Do Nothing")
        self.fail("No durable confirmation after 12 polls. The save may have completed. Read WLED Alarm Status before retrying; never clear on a network error.")

    def document(self):
        return {
            "WFWorkflowName": self.name,
            "WFWorkflowClientVersion": "5114.0.6.204",
            "WFWorkflowMinimumClientVersion": 900,
            "WFWorkflowMinimumClientVersionString": "900",
            "WFWorkflowIcon": {"WFWorkflowIconGlyphNumber": 59845, "WFWorkflowIconStartColor": 4251333119},
            "WFWorkflowActions": self.actions,
            "WFWorkflowImportQuestions": self.questions,
            "WFWorkflowTypes": ["WFWorkflowTypeShowInSearch"],
            "WFQuickActionSurfaces": [],
            "WFWorkflowInputContentItemClasses": [],
            "WFWorkflowOutputContentItemClasses": ["WFStringContentItem"],
            "WFWorkflowHasShortcutInputVariables": False,
        }


def build_sync(check_only=False):
    shortcut = Shortcut("WLED Alarm Check" if check_only else "WLED Alarm Sync")
    shortcut.comment("Read the next enabled normal Clock alarm containing WLED. Run WLED Alarm Check and verify disabled alarms, repeat days and tomorrow before enabling live sync. This does not edit iPhone or manual WLED alarms.")
    base = None if check_only else shortcut.base_url()
    live = None
    if not check_only:
        index = len(shortcut.actions)
        live = shortcut.add("number", WFNumberActionNumber=0)
        shortcut.questions.append({"Category": "Parameter", "ActionIndex": index, "ParameterKey": "WFNumberActionNumber",
                                   "Text": "Enter 1 ONLY after WLED Alarm Check selects the correct enabled WLED alarm on this iPhone. 0 keeps preview mode (no network writes).",
                                   "DefaultValue": 0})
    now, captured = shortcut.capture()
    found, best, label = shortcut.select_wake(now)
    with shortcut.condition(found, 4, 1, "number") as otherwise:
        wake = shortcut.format_date(best, WAKE_FORMAT)
        shortcut.set("WLED payload", shortcut.add("gettext", WFTextActionText=text('{"capturedAt":"', captured, '","wakeAt":"', wake, '"}')))
        shortcut.set("WLED summary", shortcut.add("gettext", WFTextActionText=text("Next WLED Clock alarm: ", label, "\nWake at: ", wake)))
        otherwise()
        shortcut.set("WLED payload", shortcut.add("gettext", WFTextActionText=text('{"capturedAt":"', captured, '","wakeAt":null}')))
        shortcut.set("WLED summary", "Successful Clock reading: no enabled WLED alarm. Live sync will clear only the managed iPhone slot.")
    summary = variable("WLED summary")
    if check_only:
        shortcut.add("showresult", Text=text(summary, "\nRead-only check: nothing was sent to WLED."))
    else:
        with shortcut.condition(live, 5, 1, "number"):
            shortcut.add("showresult", Text=text(summary, "\nPreview only. Set the first Number action to 1 AFTER validating WLED Alarm Check."))
            shortcut.add("exit")
        status = shortcut.request(text(base, SYNC_PATH))
        shortcut.require_equal(shortcut.get(status, "version"), 2, "Unexpected sync API version.")
        for key in ("supported", "configurationValid", "clockValid"):
            shortcut.require_equal(shortcut.get(status, key), 1, "WLED sync is not ready: ", key, ". Check ESP32 firmware, storage and NTP.")
        shortcut.send_confirmed(base, SYNC_PATH, variable("WLED payload"), summary)
    return shortcut


def build_setup():
    shortcut = Shortcut("WLED Alarm Setup")
    shortcut.comment("Enable the independent iPhone profile while retaining its existing light settings. The master switch, presence target and manual alarms are not changed. Configure them in /wecker.htm.")
    base = shortcut.base_url()
    profile = shortcut.request(text(base, PROFILE_PATH))
    shortcut.require_equal(shortcut.get(profile, "version"), 2, "Unexpected sync API version.")
    shortcut.require_equal(shortcut.get(profile, "supported"), 1, "Phone sync requires ESP32 firmware with wecker_presence.")
    revision = shortcut.get(profile, "revision")
    light = shortcut.get(profile, "profile")
    shortcut.require(light, "Missing light profile. No setup was sent.")
    serialized = shortcut.add("detect.text", WFInput=attachment(light))
    body = shortcut.add("gettext", WFTextActionText=text('{"revision":', revision, ',"enabled":true,"profile":', serialized, '}'))
    shortcut.send_confirmed(base, PROFILE_PATH, body, "iPhone light profile enabled; existing light settings retained. Check the master switch and phone presence in /wecker.htm.")
    return shortcut


def build_status():
    shortcut = Shortcut("WLED Alarm Status")
    shortcut.comment("Read-only view of the managed iPhone slot. The independent light profile and master switch must both be enabled for execution; phone presence also applies.")
    base = shortcut.base_url()
    status = shortcut.request(text(base, SYNC_PATH))
    shortcut.add("previewdocument", WFInput=attachment(status))
    return shortcut


def build_clear():
    shortcut = Shortcut("WLED Alarm Clear")
    shortcut.comment("Explicit manual clear of the managed iPhone slot. Never attach this shortcut to network-error handling. It does not delete or toggle Clock alarms or manual WLED alarms.")
    base = shortcut.base_url()
    shortcut.add("alert", WFAlertActionTitle="Clear WLED iPhone slot?", WFAlertActionCancelButtonShown=True,
                 WFAlertActionMessage="Clear only the managed iPhone wake instant? A running iPhone light alarm will stop. Clock alarms and manual WLED alarms are unchanged.")
    _, captured = shortcut.capture()
    body = shortcut.add("gettext", WFTextActionText=text('{"capturedAt":"', captured, '","wakeAt":null}'))
    shortcut.send_confirmed(base, SYNC_PATH, body, "Managed WLED iPhone slot cleared; Clock and manual WLED alarms unchanged.")
    return shortcut


def build_all():
    return [build_sync(True), build_setup(), build_sync(), build_status(), build_clear()]


def main():
    """Write inspectable plists, optionally requesting Apple's importable signature."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=ROOT / "build_output/ios-shortcuts")
    parser.add_argument("--sign", action="store_true", help="Requires a Mac signed into iCloud. Apple receives the generic template for validation (--mode anyone).")
    arguments = parser.parse_args()
    unsigned = arguments.output / "unsigned"
    unsigned.mkdir(parents=True, exist_ok=True)
    helper = arguments.output / "Sign on Mac.command"
    helper.write_bytes(Path(__file__).with_name("sign-on-mac.command").read_bytes())
    helper.chmod(0o755)
    (arguments.output / "INSTALL.txt").write_bytes(Path(__file__).with_name("install.txt").read_bytes())
    shortcuts = build_all()
    for shortcut in shortcuts:
        source = unsigned / (shortcut.name + ".shortcut")
        document = shortcut.document()
        source.write_bytes(plistlib.dumps(document, fmt=plistlib.FMT_XML, sort_keys=False))
        if not arguments.sign:
            print(source)
    manifest = {"target": "iOS 27.2 (device verification required)", "liveSyncDefault": False,
                "alarmLabelContains": "WLED", "caseSensitive": True, "endpoints": [SYNC_PATH, PROFILE_PATH, SYNC_PATH + "/result"],
                "signed": False, "shortcuts": [shortcut.name for shortcut in shortcuts]}
    code = 0
    if arguments.sign:
        try:
            for shortcut in shortcuts:
                source = unsigned / (shortcut.name + ".shortcut")
                destination = arguments.output / (shortcut.name + ".shortcut")
                subprocess.run(["shortcuts", "sign", "--mode", "anyone", "--input", str(source), "--output", str(destination)], check=True)
                print(destination)
            manifest["signed"] = True
        except (OSError, subprocess.CalledProcessError) as error:
            code = 1
            manifest["signingError"] = str(error)
            print("Signing failed. All five unsigned templates are available at " + str(unsigned)
                  + ". Sign on a Mac logged into iCloud before distributing/importing them.", file=sys.stderr)
    (arguments.output / "manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    # Package only this build's explicit outputs, never arbitrary/private folder contents.
    archive_name = "WLED Shortcuts - iPhone.zip" if manifest["signed"] else "WLED Shortcuts - Mac signing kit.zip"
    with zipfile.ZipFile(arguments.output / archive_name, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.write(arguments.output / "INSTALL.txt", "WLED Shortcuts/INSTALL.txt")
        if not manifest["signed"]:
            archive.write(helper, "WLED Shortcuts/Sign on Mac.command")
        for shortcut in shortcuts:
            relative = Path(shortcut.name + ".shortcut") if manifest["signed"] else Path("unsigned") / (shortcut.name + ".shortcut")
            archive.write(arguments.output / relative, str(Path("WLED Shortcuts") / relative))
    return code


if __name__ == "__main__":
    sys.exit(main())
# AI: end
